<script setup lang="ts">
import { computed, ref, watch } from "vue"
import type { Grading } from "../types/grading"
const props = defineProps<{ grading: Grading | null; retrying?: boolean }>()
const emit = defineEmits<{ retry: []; acknowledge: []; open: [] }>()
const visible = computed(() => Boolean(props.grading)); const dialogOpen = ref(false)
watch(() => [props.grading?.id, props.grading?.status], () => { if (props.grading && !props.grading.acknowledgedAt && ["SUCCEEDED", "FAILED"].includes(props.grading.status)) dialogOpen.value = true }, { immediate: true })
const isPending = computed(() => props.grading?.status === "PENDING" || props.grading?.status === "RUNNING")
const isFailed = computed(() => props.grading?.status === "FAILED"); const report = computed(() => props.grading?.report); const score = computed(() => report.value?.totalScore.toFixed(1) ?? "—")
function acknowledge() { dialogOpen.value = false; emit("acknowledge") }
function returnToSession() { if (isPending.value) { dialogOpen.value = false; return }; acknowledge() }
function openReport() { dialogOpen.value = true; emit("open") }
function retry() { dialogOpen.value = true; emit("retry") }
function beforeClose(done: () => void) { dialogOpen.value = false; done() }
</script>
<template>
  <section v-if="grading" class="grading-entry" :class="{ 'grading-entry--failed': isFailed }" aria-live="polite">
    <div class="grading-entry__icon" aria-hidden="true">{{ isFailed ? "!" : isPending ? "…" : "✓" }}</div>
    <div class="grading-entry__copy"><strong v-if="isPending">首次自讲正在评分</strong><strong v-else-if="isFailed">首次自讲评分暂未完成</strong><strong v-else>首次自讲评分已完成</strong><p v-if="isPending">评分在后台进行，你可以继续输入。</p><p v-else-if="isFailed">{{ grading.errorMessage || "评分服务暂时不可用。" }}</p><p v-else>总分 {{ score }} 分{{ grading.evaluationStatus === 'RUNNING' || grading.evaluationStatus === 'PENDING' ? " · 自讲评价仍在生成" : " · 评分结果已保留" }}</p></div>
    <el-button v-if="isFailed" data-testid="retry-grading-entry" text type="primary" :loading="retrying" @click="retry">重新评分</el-button>
    <el-button v-else-if="!isPending" data-testid="view-grading-entry" text type="primary" @click="openReport">查看评价</el-button>
  </section>
  <el-dialog :model-value="visible && dialogOpen" width="min(800px, calc(100vw - 32px))" class="grading-dialog" :close-on-click-modal="false" :close-on-press-escape="false" :show-close="true" destroy-on-close aria-label="首次自讲评价" :before-close="beforeClose">
    <template #header><div class="grading-dialog__header"><span class="grading-dialog__mark" aria-hidden="true">▤</span><div><h2>首次自讲评价</h2><p>标准版本：{{ grading?.standardVersion }}</p></div></div></template>
    <div v-if="isPending" class="grading-dialog__pending" role="status"><span class="grading-spinner" aria-hidden="true" /><h3>正在评价首次自讲</h3><p>评分正在后台进行。你可以先返回自讲继续学习。</p><el-button data-testid="acknowledge-grading-pending" @click="returnToSession">返回自讲</el-button></div>
    <div v-else-if="isFailed" class="grading-dialog__pending" role="alert"><span class="grading-error-mark" aria-hidden="true">!</span><h3>暂时未能生成评价</h3><p>{{ grading?.errorMessage || "评分服务暂时不可用。" }}</p><div><el-button data-testid="acknowledge-grading-failed" @click="returnToSession">返回自讲</el-button><el-button data-testid="retry-grading-dialog" type="primary" :loading="retrying" @click="retry">重新评分</el-button></div></div>
    <template v-else-if="report"><div class="grading-result__hero"><div class="grading-result__score"><span>自讲总分</span><strong>{{ score }}</strong><small>满分 100 分</small></div><p>{{ report.summary }}</p></div><div class="grading-result__dimensions"><article><header><h3>正确性</h3><strong>{{ report.correctnessScore }} / 4</strong></header><p class="grading-result__question">已表达的内容是否成立 · 占 50%</p><p>{{ report.correctnessReason }}</p></article><article><header><h3>完整性</h3><strong>{{ report.completenessScore }} / 4</strong></header><p class="grading-result__question">本题必要内容是否覆盖 · 占 50%</p><p>{{ report.completenessReason }}</p></article></div><section v-if="report.missingRequirements.length"><h3>尚未表达的必要内容</h3><ul><li v-for="item in report.missingRequirements" :key="item">{{ item }}</li></ul></section><details v-if="report.ambiguityNotes.length || report.rubricLimitations.length"><summary>查看评价说明</summary><div v-for="note in report.ambiguityNotes" :key="note.source"><strong>{{ note.source }}</strong><p>{{ note.interpretation }}（{{ note.impact }}）</p></div></details></template>
    <template #footer><el-button data-testid="acknowledge-grading" type="primary" @click="returnToSession">返回自讲</el-button></template>
  </el-dialog>
</template>
<style scoped>
.grading-entry{display:flex;align-items:center;gap:var(--space-3);margin:var(--space-4) 0;padding:var(--space-3) var(--space-4);border:1px solid var(--color-brand-100);border-radius:var(--radius-lg);background:var(--color-brand-50)}.grading-entry--failed{border-color:var(--color-error-100);background:#fff7f6}.grading-entry__icon{display:grid;place-items:center;width:36px;height:36px;flex:none;border-radius:50%;color:var(--color-brand-700);background:var(--color-surface);font-weight:700}.grading-entry__copy{flex:1;min-width:0}.grading-entry__copy p{margin:0;color:var(--color-text-secondary);font-size:var(--font-size-sm)}.grading-dialog__header{display:flex;align-items:center;gap:var(--space-3)}.grading-dialog__header h2,.grading-dialog__header p{margin:0}.grading-dialog__header p{color:var(--color-text-muted);font-size:var(--font-size-sm)}.grading-dialog__mark{display:grid;place-items:center;width:40px;height:40px;border-radius:var(--radius-md);color:var(--color-brand-700);background:var(--color-brand-50)}.grading-dialog__pending{display:grid;justify-items:center;gap:var(--space-3);padding:var(--space-8) var(--space-4);text-align:center}.grading-dialog__pending h3,.grading-dialog__pending p{margin:0}.grading-spinner{width:28px;height:28px;border:3px solid var(--color-brand-100);border-top-color:var(--color-brand-700);border-radius:50%;animation:grading-spin 800ms linear infinite}.grading-error-mark{display:grid;place-items:center;width:28px;height:28px;border-radius:50%;color:var(--color-error-700);background:var(--color-error-100);font-weight:700}@keyframes grading-spin{to{transform:rotate(360deg)}}.grading-result__hero{display:grid;grid-template-columns:160px 1fr;gap:var(--space-5);align-items:center}.grading-result__score{display:grid;justify-items:center;padding:var(--space-4);border:1px solid var(--color-brand-100);border-radius:var(--radius-lg);color:var(--color-brand-700);background:var(--color-brand-50)}.grading-result__score strong{font-size:42px}.grading-result__dimensions{display:grid;grid-template-columns:1fr 1fr;gap:var(--space-4);margin-top:var(--space-5)}.grading-result__dimensions article{padding:var(--space-4);border:1px solid var(--color-border);border-radius:var(--radius-md)}.grading-result__dimensions header{display:flex;justify-content:space-between}.grading-result__question{color:var(--color-text-muted);font-size:var(--font-size-sm)}@media(max-width:640px){.grading-result__hero,.grading-result__dimensions{grid-template-columns:1fr}}
</style>
